static void pu(FILE*f,sda_u128 x){char b[64];sda_print_u128(x,b,sizeof b);fputs(b,f);}
static int md(const char*p){return mkdir(p,0777)==0||errno==EEXIST?0:-1;}
int sda_candidate_set_init(sda_candidate_set*s,mpfr_prec_t p){if(!s)return-1;memset(s,0,sizeof *s);s->precision=p;return 0;}
void sda_candidate_set_clear(sda_candidate_set*s){if(!s)return;for(size_t i=0;i<s->count;i++)mpfr_clears(s->items[i].pointwise,s->items[i].sd,s->items[i].rd,s->items[i].epsilon_min,s->items[i].epsilon_max,s->items[i].frozen_l1,s->items[i].frozen_max,s->items[i].frozen_log2_q,(mpfr_ptr)0);free(s->items);memset(s,0,sizeof *s);}
int sda_candidate_set_add(sda_candidate_set*s,size_t n,sda_u128 q,const sda_u128*p,const sda_u128*c,unsigned trial,const char*eps,mpfr_t point,mpfr_t sd,mpfr_t rd,unsigned*qflags){
 for(size_t i=0;i<s->count;i++)if(s->items[i].n==n&&s->items[i].q==q&&!memcmp(s->items[i].p,p,n*sizeof *p)){s->items[i].occurrences++;if(qflags)*qflags=s->items[i].quality_flags;return 0;}
 if(s->count==s->capacity){size_t nc=s->capacity?s->capacity*2:16;sda_ranked_candidate*x=realloc(s->items,nc*sizeof *x);if(!x)return-1;s->items=x;s->capacity=nc;}
 sda_ranked_candidate*x=&s->items[s->count];memset(x,0,sizeof *x);x->n=n;x->q=q;x->first_trial=trial;x->occurrences=1;memcpy(x->p,p,n*sizeof *p);memcpy(x->c,c,n*sizeof *c);snprintf(x->epsilon,sizeof x->epsilon,"%s",eps);mpfr_inits2(s->precision,x->pointwise,x->sd,x->rd,x->epsilon_min,x->epsilon_max,x->frozen_l1,x->frozen_max,x->frozen_log2_q,(mpfr_ptr)0);mpfr_set(x->pointwise,point,MPFR_RNDN);mpfr_set(x->sd,sd,MPFR_RNDN);mpfr_set(x->rd,rd,MPFR_RNDN);x->quality_flags=qflags?*qflags:0;s->count++;return 1;
}
int sda_candidate_set_observe(sda_candidate_set*s,size_t n,sda_u128 q,const sda_u128*p,const sda_u128*c,unsigned seq,unsigned stage,unsigned grid,mpfr_t eps,int inside,mpfr_t point,mpfr_t sd,mpfr_t rd,unsigned flags,const char*hash,size_t*id){char es[192];mpfr_snprintf(es,sizeof es,"%.160Re",eps);size_t before=s->count;int rc=sda_candidate_set_add(s,n,q,p,c,seq,es,point,sd,rd,&flags);if(rc<0)return rc;size_t k=before;if(!rc)for(k=0;k<s->count;k++)if(s->items[k].n==n&&s->items[k].q==q&&!memcmp(s->items[k].p,p,n*sizeof*p))break;sda_ranked_candidate*x=&s->items[k];if(rc>0){x->first_stage=x->last_stage=stage;x->contiguous_run_count=1;x->last_sequence=seq;x->inside_paper_interval=(unsigned)inside;mpfr_set(x->epsilon_min,eps,MPFR_RNDN);mpfr_set(x->epsilon_max,eps,MPFR_RNDN);snprintf(x->basis_hash,sizeof x->basis_hash,"%s",hash?hash:"");}else{x->last_stage=stage;if(x->last_sequence+1!=seq)x->contiguous_run_count++;x->last_sequence=seq;if(mpfr_cmp(eps,x->epsilon_min)<0)mpfr_set(x->epsilon_min,eps,MPFR_RNDN);if(mpfr_cmp(eps,x->epsilon_max)>0)mpfr_set(x->epsilon_max,eps,MPFR_RNDN);(void)inside;}(void)grid;if(id)*id=k;return rc;}
static int metric_kind;
static int cmp(const void*A,const void*B){const sda_ranked_candidate*a=*(const sda_ranked_candidate*const*)A,*b=*(const sda_ranked_candidate*const*)B;int c=metric_kind==0?mpfr_cmp(a->pointwise,b->pointwise):metric_kind==1?mpfr_cmp(a->sd,b->sd):metric_kind==2?mpfr_cmp(a->rd,b->rd):(a->q>b->q)-(a->q<b->q);if(c)return c;if(a->q!=b->q)return a->q<b->q?-1:1;return (a->first_trial>b->first_trial)-(a->first_trial<b->first_trial);}
static void vec(FILE*f,const char*n,const sda_u128*v,size_t z){fprintf(f,"%s=",n);for(size_t i=0;i<z;i++){if(i)fputc(' ',f);pu(f,v[i]);}fputc('\n',f);}
static void rank(FILE*f,sda_candidate_set*s,const char*name,int kind,unsigned top){sda_ranked_candidate**v=malloc(s->count*sizeof *v);if(!v)return;for(size_t i=0;i<s->count;i++)v[i]=&s->items[i];metric_kind=kind;qsort(v,s->count,sizeof *v,cmp);fprintf(f,"[%s]\n",name);size_t z=s->count<top?s->count:top;for(size_t i=0;i<z;i++){sda_ranked_candidate*x=v[i];fprintf(f,"rank=%zu trial=%u epsilon=%s q=",i+1,x->first_trial,x->epsilon);pu(f,x->q);fprintf(f," pointwise=");mpfr_out_str(f,10,0,x->pointwise,MPFR_RNDN);fprintf(f," SD=");mpfr_out_str(f,10,0,x->sd,MPFR_RNDN);fprintf(f," RD=");mpfr_out_str(f,10,0,x->rd,MPFR_RNDN);fprintf(f," quality_flags=0x%x frozen_table_identical=false\n",x->quality_flags);vec(f,"p",x->p,x->n);vec(f,"cumulative",x->c,x->n);}fputc('\n',f);free(v);}
static int outputs(const sda_config*c,uint64_t master,uint64_t seed,unsigned requested,unsigned completed,unsigned success,unsigned valid,const unsigned rej[8],sda_candidate_set*s,unsigned top,unsigned compact,const char*version,unsigned backend_fail,unsigned recover,unsigned rows){char base[160],dir[180],path[240];snprintf(base,sizeof base,"offline/generated/%s",c->parameter_set);snprintf(dir,sizeof dir,"%s/search",base);if(md("offline/generated")||md(base)||md(dir))return-1;snprintf(path,sizeof path,"%s/all_unique_candidates.csv",dir);FILE*f=fopen(path,"w");if(!f)return-1;fprintf(f,"candidate_id,first_trial,first_epsilon,occurrence_count,q,q_bit_length,max_pointwise_error,pointwise_target_met,SD,sd_baseline_met,RD,rd_target_met,structurally_valid,k_bit_compact,frozen_table_identical,p,cumulative\n");mpfr_t target;mpfr_init2(target,c->mpfr_precision);mpfr_set_ui_2exp(target,1,-c->precision_k,MPFR_RNDN);for(size_t i=0;i<s->count;i++){sda_ranked_candidate*x=&s->items[i];fprintf(f,"%zu,%u,%s,%u,",i+1,x->first_trial,x->epsilon,x->occurrences);pu(f,x->q);fprintf(f,",%d,",sda_bitlength_u128(x->q));mpfr_out_str(f,10,0,x->pointwise,MPFR_RNDN);fprintf(f,",%s,",mpfr_cmp(x->pointwise,target)<=0?"true":"false");mpfr_out_str(f,10,0,x->sd,MPFR_RNDN);fprintf(f,",%s,",(x->quality_flags&2)?"false":"true");mpfr_out_str(f,10,0,x->rd,MPFR_RNDN);fprintf(f,",%s,true,%s,false,\"",(x->quality_flags&4)?"false":"true",mpfr_cmp(x->pointwise,target)<=0?"true":"false");for(size_t j=0;j<x->n;j++){if(j)fputc(' ',f);pu(f,x->p[j]);}fprintf(f,"\",\"");for(size_t j=0;j<x->n;j++){if(j)fputc(' ',f);pu(f,x->c[j]);}fprintf(f,"\"\n");}fclose(f);for(size_t i=0;i<s->count;i++){snprintf(path,sizeof path,"%s/candidate_%zu.txt",dir,i+1);f=fopen(path,"w");if(!f){mpfr_clear(target);return-1;}fprintf(f,"parameter_set=%s\nq=",c->parameter_set);pu(f,s->items[i].q);fputc(10,f);vec(f,"p",s->items[i].p,s->items[i].n);vec(f,"cumulative",s->items[i].c,s->items[i].n);fclose(f);}snprintf(path,sizeof path,"%s/top_candidates.txt",dir);f=fopen(path,"w");if(!f){mpfr_clear(target);return-1;}rank(f,s,"pointwise_top",0,top);rank(f,s,"sd_top",1,top);rank(f,s,!strcmp(c->scheme,"Falcon")?"r509_top":"rd_top",2,top);rank(f,s,"smallest_q_top",3,top);fprintf(f,"[k_bit_compact_top]\n");sda_ranked_candidate**v=malloc(s->count*sizeof*v);size_t vn=0;if(v){for(size_t i=0;i<s->count;i++)if(mpfr_cmp(s->items[i].pointwise,target)<=0)v[vn++]=&s->items[i];metric_kind=3;qsort(v,vn,sizeof*v,cmp);for(size_t i=0;i<vn&&i<top;i++){fprintf(f,"rank=%zu trial=%u epsilon=%s q=",i+1,v[i]->first_trial,v[i]->epsilon);pu(f,v[i]->q);fputc('\n',f);vec(f,"p",v[i]->p,v[i]->n);vec(f,"cumulative",v[i]->c,v[i]->n);}free(v);}fclose(f);snprintf(path,sizeof path,"%s/search_summary.txt",dir);f=fopen(path,"w");if(!f){mpfr_clear(target);return-1;}fprintf(f,"parameter_set=%s\nmaster_seed=%llu\nparameter_seed=%llu\nrequested_trials=%u\ncompleted_trials=%u\ninterrupted=false\nsolver_success_count=%u\nstructurally_valid_count=%u\nunique_candidate_count=%zu\nduplicate_candidate_count=%u\nk_bit_compact_count=%u\nfrozen_table_found_in_search=false\nsolver_failure_count=%u\nq_zero_count=%u\nq_too_large_count=%u\nnegative_mass_count=%u\nsum_mismatch_count=%u\ncumulative_mismatch_count=%u\nsupport_failure_count=%u\ninternal_zero_count=%u\n",c->parameter_set,(unsigned long long)master,(unsigned long long)seed,requested,completed,success,valid,s->count,valid-(unsigned)s->count,compact,rej[0],rej[1],rej[2],rej[3],rej[4],rej[5],rej[6],rej[7]);if(version)fprintf(f,"fplll_version=%s\nBKZ_block_size=20\nbackend_failure_count=%u\nrecoverable_row_count=%u\nstructurally_valid_row_count=%u\nbkz_seed_controlled=false\n",version,backend_fail,recover,rows);fclose(f);mpfr_clear(target);return 0;}
int sda_random_generate_config(const char*path,uint64_t master,unsigned trials,unsigned top,const char*diagpath){sda_config c;if(sda_config_load(path,&c))return 1;size_t n=(size_t)(c.support_max-c.support_min+1);uint64_t seed=sda_parameter_seed(master,c.parameter_set);sda_epsilon_rng rng;sda_epsilon_rng_init(&rng,seed);mpfr_t lo,hi,eps;mpfr_inits2(c.mpfr_precision,lo,hi,eps,(mpfr_ptr)0);sda_epsilon_bounds(c.precision_k,n,lo,hi);sda_candidate_set set;sda_candidate_set_init(&set,c.mpfr_precision);FILE*d=diagpath?fopen(diagpath,"w"):0;if(d)fprintf(d,"parameter_set,trial_index,epsilon,solver_return_code,structural_reject_flags,quality_flags,structurally_valid\n");unsigned completed=0,success=0,valid=0,compact=0,rej[8]={0},backend=0,recover=0,rows=0;char version[128]={0};int falcon=!strcmp(c.scheme,"Falcon");if(falcon&&!sda_falcon_bkz_available(version,sizeof version)){fprintf(stderr,"falcon backend unavailable\n");if(d)fclose(d);sda_candidate_set_clear(&set);mpfr_clears(lo,hi,eps,(mpfr_ptr)0);return 2;}for(unsigned t=1;t<=trials;t++){sda_epsilon_random(&rng,lo,hi,eps);char es[192];mpfr_snprintf(es,sizeof es,"%.160Re",eps);unsigned structural=0,quality=0;sda_u128 p[32]={0},cum[32]={0},q=0;mpfr_t point,sd,rd;mpfr_inits2(c.mpfr_precision,point,sd,rd,(mpfr_ptr)0);int rc=0;if(!falcon){sda_candidate_diagnostic x;sda_candidate_diagnostic_init(&x,c.mpfr_precision);rc=sda_diagnose_frodo_epsilon(&c,eps,&x);structural=x.reject_flags;quality=x.quality_flags;q=x.q;memcpy(p,x.p,n*sizeof*p);if(x.solver_completed)success++;if(!structural){sda_build_cumulative(p,n,cum,&q);mpfr_set(point,x.max_pointwise,MPFR_RNDN);mpfr_set(sd,x.sd,MPFR_RNDN);mpfr_set(rd,x.rd,MPFR_RNDN);}sda_candidate_diagnostic_clear(&x);}else{mpfr_t a[32],tail,gs;for(size_t i=0;i<n;i++)mpfr_init2(a[i],c.mpfr_precision);mpfr_inits2(c.mpfr_precision,tail,gs,(mpfr_ptr)0);sda_generate_distribution(&c,a,n,tail,gs);sda_falcon_bkz_result b;rc=sda_falcon_bkz_solve(a,eps,c.mpfr_precision,seed+t,&b);recover+=(unsigned)b.recoverable_row_count;rows+=(unsigned)b.structurally_valid_row_count;if(rc){structural|=SDA_REJECT_SOLVER;backend++;}else{success++;q=b.q;memcpy(p,b.p,n*sizeof*p);sda_u128 sum=0;int zero=0;for(size_t i=0;i<n;i++){sum+=p[i];if(!p[i])zero=1;else if(zero)structural|=SDA_REJECT_ZERO_HOLE;}if(!q)structural|=SDA_REJECT_Q_ZERO;if(q>=((sda_u128)1<<72))structural|=SDA_REJECT_Q_LARGE;if(sum!=q)structural|=SDA_REJECT_SUM;if(!structural){sda_build_cumulative(p,n,cum,&q);sda_metrics m;sda_metrics_init(&m,c.mpfr_precision);sda_compute_metrics(a,n,p,q,509,&m);mpfr_set(point,m.max_absolute_error,MPFR_RNDN);mpfr_set(sd,m.sd_support,MPFR_RNDN);mpfr_set(rd,m.renyi,MPFR_RNDN);mpfr_t z;mpfr_init2(z,c.mpfr_precision);mpfr_set_ui_2exp(z,1,-72,MPFR_RNDN);if(mpfr_cmp(point,z)>0)quality|=1;mpfr_set_ui_2exp(z,1,-78,MPFR_RNDN);mpfr_add_ui(z,z,1,MPFR_RNDN);if(mpfr_cmp(rd,z)>0)quality|=4;mpfr_clear(z);sda_metrics_clear(&m);}}for(size_t i=0;i<n;i++)mpfr_clear(a[i]);mpfr_clears(tail,gs,(mpfr_ptr)0);}completed++;for(int i=0;i<8;i++)if(structural&(1u<<i))rej[i]++;if(!structural){valid++;mpfr_t z;mpfr_init2(z,c.mpfr_precision);mpfr_set_ui_2exp(z,1,-c.precision_k,MPFR_RNDN);if(mpfr_cmp(point,z)<=0)compact++;mpfr_clear(z);if(sda_candidate_set_add(&set,n,q,p,cum,t,es,point,sd,rd,&quality)<0){mpfr_clears(point,sd,rd,(mpfr_ptr)0);if(d)fclose(d);sda_candidate_set_clear(&set);mpfr_clears(lo,hi,eps,(mpfr_ptr)0);return 1;}}if(d)fprintf(d,"%s,%u,%s,%d,0x%x,0x%x,%s\n",c.parameter_set,t,es,rc,structural,quality,structural?"false":"true");mpfr_clears(point,sd,rd,(mpfr_ptr)0);}if(d)fclose(d);compact=0;mpfr_t compact_target;mpfr_init2(compact_target,c.mpfr_precision);mpfr_set_ui_2exp(compact_target,1,-c.precision_k,MPFR_RNDN);for(size_t i=0;i<set.count;i++)if(mpfr_cmp(set.items[i].pointwise,compact_target)<=0)compact++;mpfr_clear(compact_target);int out=outputs(&c,master,seed,trials,completed,success,valid,rej,&set,top,compact,falcon?version:0,backend,recover,rows);fprintf(stderr,"%s requested_trials=%u completed_trials=%u solver_success_count=%u structurally_valid_count=%u unique_candidate_count=%zu duplicate_candidate_count=%u k_bit_compact_count=%u\n",c.parameter_set,trials,completed,success,valid,set.count,valid-(unsigned)set.count,compact);sda_candidate_set_clear(&set);mpfr_clears(lo,hi,eps,(mpfr_ptr)0);return out?1:0;}
